"""Shipping zone, cost and oversize helpers (task D2)."""


def shipping_zone(country_code):
    """Return the shipping zone for a country code.

    DE -> 1, FR or NL -> 2, anything else -> 3.
    """
    if country_code == "DE":
        return 1
    if country_code in ("FR", "NL"):
        return 2
    return 3


_BASE_BY_ZONE = {1: 4.5, 2: 9.0, 3: 20.0}


def shipping_cost(weight_kg, zone):
    """Return base + 1.5 * weight_kg, rounded to 2 decimals.

    Base is 4.5 for zone 1, 9.0 for zone 2 and 20.0 for zone 3.
    """
    base = _BASE_BY_ZONE[zone]
    return round(base + 1.5 * weight_kg, 2)


def is_oversize(l, w, h):
    """Return True if any dimension exceeds 120 or l + w + h exceeds 300."""
    if l > 120 or w > 120 or h > 120:
        return True
    return l + w + h > 300

